name = 'se', seed = 0
@pytest.mark.parametrize("seed", [0, 1, 2]) @pytest.mark.parametrize("name", ["se", "m52"]) def test_fit_branin(name, seed): X = branin_design(30, seed) y = branin(X) gp = GPRegressor(KERNELS[name](np.ones(2), 1.0), noise=1e-6, normalize_y=True) gp.fit(X, y) ls, var, noise = np.asarray(gp.kernel.lengthscales), float(gp.kernel.variance), float(gp.noise) mine = ref_lml(name, X, y, ls, var, noise, True) # 1. the objective it optimised is the true log marginal likelihood assert gp.log_marginal_likelihood() == pytest.approx(mine, rel=1e-3, abs=0.05) # 2. it reaches the optimum found by scikit-learn (same model), within 2 nats sk = ref_lml(name, X, y, *sklearn_optimum(name, X, y), True) > assert mine >= sk - 2.0, f"LML {mine:.2f} < scikit-learn optimum {sk:.2f}" E AssertionError: LML -1.46 < scikit-learn optimum 18.39 E assert np.float64(-1.456747783853725) >= (np.float64(18.386428831473918) - 2.0)
